// Worker Enrollment never implies trust; see eligibility. poolId is absent while the worker is unassigned, and an unassigned worker receives no builds (ADR 0045). A worker receives builds only while it is connected and eligible.
type Worker struct {
	// BundleVersion Trust-bundle version the worker acknowledged
	BundleVersion *int64 `json:"bundleVersion,omitempty"`
	Capabilities  *struct {
		Architectures *[]string `json:"architectures,omitempty"`

		// ConfigDigest Digest of the worker's security-relevant configuration
		ConfigDigest *string `json:"configDigest,omitempty"`

		// DaemonSlots Free one-build daemons (OD-16)
		DaemonSlots       *int                  `json:"daemonSlots,omitempty"`
		Engines           *[]string             `json:"engines,omitempty"`
		IsolationProfiles *[]string             `json:"isolationProfiles,omitempty"`
		Os                *WorkerCapabilitiesOs `json:"os,omitempty"`
	} `json:"capabilities,omitempty"`
	CertificateExpiresAt *Timestamp `json:"certificateExpiresAt,omitempty"`
	CompromisedSince     *Timestamp `json:"compromisedSince,omitempty"`

	// Connected The worker holds a live stream to a running controller now
	Connected   bool `json:"connected"`
	Eligibility struct {
		Reasons         []WorkerEligibilityReasons `json:"reasons"`
		UntrustedBuilds bool                       `json:"untrustedBuilds"`
	} `json:"eligibility"`
	EnrollmentState WorkerEnrollmentState `json:"enrollmentState"`

	// Id ULID
	Id               Id                     `json:"id"`
	LastSeenAt       *Timestamp             `json:"lastSeenAt,omitempty"`
	Name             string                 `json:"name"`
	OperationalState WorkerOperationalState `json:"operationalState"`

	// PoolId ULID
	PoolId *Id `json:"poolId,omitempty"`

	// Removal Present once an administrator removed the worker (ADR 0045)
	Removal *struct {
		Detail      *string               `json:"detail,omitempty"`
		Outcome     *WorkerRemovalOutcome `json:"outcome,omitempty"`
		Reason      string                `json:"reason"`
		RequestedAt Timestamp             `json:"requestedAt"`
		State       WorkerRemovalState    `json:"state"`
	} `json:"removal,omitempty"`
	RevokeReason *string    `json:"revokeReason,omitempty"`
	RevokedAt    *Timestamp `json:"revokedAt,omitempty"`

	// SelfTest The worker's newest finished self-test; current is false when the profile or configuration changed since
	SelfTest struct {
		ConfigDigest *string              `json:"configDigest,omitempty"`
		Current      bool                 `json:"current"`
		FailedChecks *[]string            `json:"failedChecks,omitempty"`
		FinishedAt   *Timestamp           `json:"finishedAt,omitempty"`
		Profile      *string              `json:"profile,omitempty"`
		Running      *bool                `json:"running,omitempty"`
		Status       WorkerSelfTestStatus `json:"status"`
	} `json:"selfTest"`
	Version *string `json:"version,omitempty"`
}

